  1860                  }
  1861                  free(entry->u.rc);
  1862                  free(entry);
  1863                  break;
  1864              }
  1865          case LEAK_PTR:
  1866              free(entry->u.ptr);
  1867              free(entry);
  1868              break;
  1869          default:
  1870              sudo_warnx("unexpected garbage type %d", entry->type);
  1871          }
  1872      }
  1873
  1874      debug_return;
  1875  #endif /* NO_LEAKS */
  1876  }
  1877
  1878  void
  1879  parser_leak_init(void)
  1880  {
  1881  #ifdef NO_LEAKS
  1882      static bool initialized;
  1883      debug_decl(parser_leak_init, SUDOERS_DEBUG_PARSER);
  1884
  1885      if (!initialized) {
  1886          atexit(parser_leak_free);
  1887          initialized = true;
  1888          debug_return;
  1889      }
  1890
  1891      /* Already initialized, free existing leaks. */
  1892      parser_leak_free();
  1893      debug_return;
  1894  #endif /* NO_LEAKS */
  1895  }

