  1682  bool
  1683  parser_leak_add(enum parser_leak_types type, void *v)
  1684  {
  1685  #ifdef NO_LEAKS
  1686      struct parser_leak_entry *entry;
  1687      debug_decl(parser_leak_add, SUDOERS_DEBUG_PARSER);
  1688
  1689      if (v == NULL)
  1690          debug_return_bool(false);
  1691
  1692      entry = calloc(1, sizeof(*entry));
  1693      if (entry == NULL) {
  1694          sudo_warnx(U_("%s: %s"), __func__, U_("unable to allocate memory"));
  1695          debug_return_bool(false);
  1696      }
  1697      switch (type) {
  1698      case LEAK_PRIVILEGE:
  1699          entry->u.p = v;
  1700          break;
  1701      case LEAK_CMNDSPEC:
  1702          entry->u.cs = v;
  1703          break;
  1704      case LEAK_DEFAULTS:
  1705          entry->u.d = v;
  1706          break;
  1707      case LEAK_MEMBER:
  1708          entry->u.m = v;
  1709          break;
  1710      case LEAK_DIGEST:
  1711          entry->u.dig = v;
  1712          break;
  1713      case LEAK_RUNAS:
  1714          entry->u.rc = v;
  1715          break;
  1716      case LEAK_PTR:
  1717          entry->u.ptr = v;
  1718          break;
  1719      default:
  1720          free(entry);
  1721          sudo_warnx("unexpected leak type %d", type);
  1722          debug_return_bool(false);
  1723      }
  1724      entry->type = type;
  1725      SLIST_INSERT_HEAD(&parser_leak_list, entry, entries);
  1726      debug_return_bool(true);
  1727  #else
  1728      return true;
  1729  #endif /* NO_LEAKS */
  1730  }
  1731
  1732  bool
  1733  parser_leak_remove(enum parser_leak_types type, void *v)
  1734  {
  1735  #ifdef NO_LEAKS
  1736      struct parser_leak_entry *entry, *prev = NULL;
  1737      debug_decl(parser_leak_remove, SUDOERS_DEBUG_PARSER);
  1738
  1739      if (v == NULL)
  1740          debug_return_bool(false);
  1741
  1742      SLIST_FOREACH(entry, &parser_leak_list, entries) {
  1743          switch (entry->type) {
  1744          case LEAK_PRIVILEGE:
  1745              if (entry->u.p == v)
  1746                  goto found;
  1747              break;
  1748          case LEAK_CMNDSPEC:
  1749              if (entry->u.cs == v)
  1750                  goto found;
  1751              break;
  1752          case LEAK_DEFAULTS:
  1753              if (entry->u.d == v)
  1754                  goto found;
  1755              break;
  1756          case LEAK_MEMBER:
  1757              if (entry->u.m == v)
  1758                  goto found;
  1759              break;
  1760          case LEAK_DIGEST:
  1761              if (entry->u.dig == v)
  1762                  goto found;
  1763              break;
  1764          case LEAK_RUNAS:
  1765              if (entry->u.rc == v)
  1766                  goto found;
  1767              break;
  1768          case LEAK_PTR:
  1769              if (entry->u.ptr == v)
  1770                  goto found;
  1771              break;
  1772          default:
  1773              sudo_warnx("unexpected leak type %d in %p", entry->type, entry);
  1774          }
  1775          prev = entry;
  1776      }
  1777      /* If this happens, there is a bug in the leak tracking code. */
  1778      sudo_warnx("%s: unable to find %p, type %d", __func__, v, type);
  1779      return false;
  1780  found:
  1781      if (prev == NULL)
  1782          SLIST_REMOVE_HEAD(&parser_leak_list, entries);
  1783      else
  1784          SLIST_REMOVE_AFTER(prev, entries);
  1785      free(entry);
  1786      return true;
  1787  #endif /* NO_LEAKS */
  1788  }

